"""Retire only the unmodified configuration generated by anomaly/tmux 1.0.4."""

import hashlib
import os
from pathlib import Path
import re
import stat
import uuid


# Normalize the module's sole configurable value before checking its exact body.
# Reference: coder/registry registry/anomaly/modules/tmux/scripts/run.sh (1.0.4).
LEGACY_SHA256 = "e45a0903111e83c29f608989536af754f60b70f4e8974f8aad4ababeb2d287f4"


def retire(home):
    config = home / ".tmux.conf"
    try:
        info = config.lstat()
    except FileNotFoundError:
        return None
    if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_uid != os.geteuid():
        print("Preserving linked or externally owned tmux configuration; review snapshot settings.")
        return None
    try:
        content = config.read_text()
    except UnicodeError:
        return None
    normalized = re.sub(
        r"(?m)^set -g @continuum-save-interval '[0-9]+'$",
        "set -g @continuum-save-interval '__HIVE_SAVE_INTERVAL__'",
        content,
    )
    if hashlib.sha256(normalized.encode()).hexdigest() != LEGACY_SHA256:
        if re.search(r"resurrect|continuum", content):
            print("Preserving custom tmux configuration; review any snapshot plugins it enables.")
        return None
    current = config.lstat()
    if (current.st_ino, current.st_mtime_ns) != (info.st_ino, info.st_mtime_ns):
        raise RuntimeError("tmux configuration changed during migration; retry workspace startup")
    backup = home / f".tmux.conf.hive-retired-{uuid.uuid4().hex}"
    config.rename(backup)
    backup.chmod(0o600)
    print(f"Retired generated tmux save/restore configuration; original preserved at {backup}")
    return backup


if __name__ == "__main__":
    retire(Path.home())
